  M.HEAPU8.fill(0, p, p + words * 4);
  const i32 = (i, v) => M.setValue(p + i * 4, v, 'i32');
  const f32 = (i, v) => M.setValue(p + i * 4, v, 'float');
  i32(0, SAMPLE_RATE); i32(1, 80);
  i32(2, enc); i32(3, dec); i32(4, joi);
